using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Saas.Modules;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.SuperAdmin.Clients;[Authorize(Policy="SuperAdminOnly")]public sealed class ModulesModel(OrcaFacilDbContext db,IAccountModuleSubscriptionService subscriptions):PageModel{public Guid ClientKey{get;private set;}public IReadOnlyList<Row>Modules{get;private set;}=[];public async Task<IActionResult>OnGetAsync(Guid id,CancellationToken ct){if(!await db.BusinessAccounts.AnyAsync(x=>x.Id==id&&!x.IsDeleted,ct))return NotFound();ClientKey=id;Modules=await db.SaasModules.AsNoTracking().Where(x=>x.IsActive&&!x.IsDeleted).GroupJoin(db.AccountModuleSubscriptions.AsNoTracking().Where(x=>x.AccountId==id&&!x.IsDeleted),m=>m.Id,s=>s.ModuleId,(m,s)=>new{m,s=s.FirstOrDefault()}).OrderBy(x=>x.m.DisplayOrder).Select(x=>new Row(x.m.Id,x.m.Code,x.m.DisplayName,x.s==null?null:x.s.Id,x.s==null?"Não contratado":x.s.Status.ToString(),x.s==null?x.m.BaseMonthlyPrice:x.s.ContractedPrice,x.s==null?"Monthly":x.s.BillingPeriod.ToString())).ToListAsync(ct);return Page();}public async Task<IActionResult>OnPostRequestAsync(Guid id,string moduleCode,CancellationToken ct){await subscriptions.RequestAsync(id,moduleCode,"Monthly",Actor(),ct);return RedirectToPage(new{id});}public async Task<IActionResult>OnPostActivateAsync(Guid id,Guid moduleId,decimal price,CancellationToken ct){await subscriptions.ActivateAsync(id,moduleId,price,Actor(),ct);return RedirectToPage(new{id});}public async Task<IActionResult>OnPostSuspendAsync(Guid id,Guid moduleId,string reason,CancellationToken ct){await subscriptions.SuspendAsync(id,moduleId,Actor(),reason,ct);return RedirectToPage(new{id});}public async Task<IActionResult>OnPostTrialAsync(Guid id,Guid moduleId,DateTime endsAt,CancellationToken ct){await subscriptions.StartTrialAsync(id,moduleId,endsAt,Actor(),ct);return RedirectToPage(new{id});}public async Task<IActionResult>OnPostManualAsync(Guid id,Guid moduleId,DateTime endsAt,string reason,CancellationToken ct){await subscriptions.GrantManualAsync(id,moduleId,endsAt,reason,Actor(),ct);return RedirectToPage(new{id});}public async Task<IActionResult>OnPostPriceAsync(Guid id,Guid moduleId,decimal price,decimal discount,CancellationToken ct){await subscriptions.UpdatePriceAsync(id,moduleId,price,discount,Actor(),ct);return RedirectToPage(new{id});}public async Task<IActionResult>OnPostCancelAsync(Guid id,Guid moduleId,string reason,CancellationToken ct){await subscriptions.CancelAsync(id,moduleId,Actor(),reason,ct);return RedirectToPage(new{id});}private Guid Actor()=>Guid.TryParse(User.FindFirstValue("user_id"),out var x)?x:Guid.Empty;public sealed record Row(Guid ModuleKey,string Code,string Name,Guid? SubscriptionKey,string Status,decimal Price,string Period);}
